{
  "compilerOptions": {
    "target": "ES2017",
    "lib": ["dom", "dom.iterable", "esnext"],
    "allowJs": true,
    "skipLibCheck": true,
    "strict": true,
    "noEmit": true,
    "esModuleInterop": true,
    "module": "esnext",
    "moduleResolution": "bundler",
    "resolveJsonModule": true,
    "isolatedModules": true,
    "jsx": "preserve",
    "incremental": true,
    "plugins": [
      {
        "name": "next"
      }
    ],
    "paths": {
      "@/*": ["./src/*"]
    }
  },
  "include": ["next-env.d.ts", "**/*.ts", "**/*.tsx", ".next/types/**/*.ts"],
  "exclude": ["node_modules"]
}

import { dirname } from 'path';
import { fileURLToPath } from 'url';
import { FlatCompat } from '@eslint/eslintrc';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const compat = new FlatCompat({
  baseDirectory: __dirname,
});

const eslintConfig = [
  {
    ignores: [
      '.next/**',
      'out/**',
      'build/**',
      'node_modules/**',
      '.opencode/**',
      'next-env.d.ts',
    ],
  },
  ...compat.extends('next/core-web-vitals', 'next/typescript'),
];

export default eslintConfig;

BEGIN;

CREATE TABLE waitlist (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    email VARCHAR(255) NOT NULL UNIQUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_email ON waitlist (email);
CREATE INDEX idx_waitlist_created_at ON waitlist (created_at);

COMMIT;

CREATE TYPE non_resident_waitlist_type AS ENUM (
    'individual',
    'company'
);

CREATE TABLE non_resident_waitlists (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    first_name VARCHAR(100) NOT NULL,
    last_name VARCHAR(100) NOT NULL,
    company_name VARCHAR(255),
    email VARCHAR(255) NOT NULL UNIQUE,
    country_id SERIAL REFERENCES countries(id) ON DELETE SET NULL,
    type non_resident_waitlist_type NOT NULL DEFAULT 'individual',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_non_resident_waitlists_type ON non_resident_waitlists(type);
CREATE INDEX idx_non_resident_waitlists_country_id ON non_resident_waitlists(country_id);
CREATE INDEX idx_non_resident_waitlists_created_at_id ON non_resident_waitlists(created_at DESC, id);

BEGIN;

set lock_timeout = '2s';
set statement_timeout = '10s';

CREATE TABLE IF NOT EXISTS user_organizations (
    user_id UUID REFERENCES users(id) ON DELETE CASCADE UNIQUE,
    name VARCHAR(255)
);

INSERT INTO user_organizations (user_id, name)
SELECT
    id,
    company_name
FROM users
WHERE
    type = 'company'
  AND company_name IS NOT NULL
  AND company_name != ''
ON CONFLICT (user_id) DO NOTHING;


CREATE INDEX idx_user_organizations_name ON user_organizations(name);

ALTER TYPE user_type RENAME VALUE 'company' TO 'organization';

ALTER TABLE users DROP COLUMN IF EXISTS company_name;

reset lock_timeout;
reset statement_timeout;

COMMIT;

BEGIN;

DROP INDEX IF EXISTS idx_users_email;
DROP INDEX IF EXISTS idx_users_particle_id;
DROP INDEX IF EXISTS idx_users_phone_number;
DROP INDEX IF EXISTS idx_email;
DROP INDEX IF EXISTS idx_wallets_public_address;

COMMIT;

BEGIN;

ALTER TABLE users
    RENAME COLUMN particle_id TO openfort_user_id;

ALTER INDEX IF EXISTS idx_users_particle_id
    RENAME TO idx_users_openfort_user_id;

COMMIT;

