export function findMissingServerEnv(features: ServerEnvFeature[]) {
  return features.flatMap((feature) =>
    requiredEnvByFeature[feature].filter((name) => !readOptionalString(name))
  );
}

export function requireServerEnv(features: ServerEnvFeature[]) {
  const missing = findMissingServerEnv(features);

  if (missing.length > 0) {
    throw new Error(
      `Missing server environment variables: ${missing.join(', ')}`
    );
  }

  return getServerEnv();
