import { NextRequest, NextResponse } from 'next/server';

import { getServerEnv } from '@/server/env';
import { ApiError, handleApiError } from '@/server/http';
import { logger } from '@/server/logger';

export async function POST(request: NextRequest) {
  try {
    const { shield } = getServerEnv();

    if (
      !shield.publishableKey ||
      !shield.secretKey ||
      !shield.encryptionShare
    ) {
      throw new ApiError(
        'INTERNAL_SERVER_ERROR',
        'Shield credentials not configured on server'
      );
    }

    const body = await request.json();

    const response = await fetch(`${shield.url}/project/encryption-session`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': shield.publishableKey,
        'x-api-secret': shield.secretKey,
      },
      body: JSON.stringify({
        encryption_part: shield.encryptionShare,
        user_id: body.user_id,
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      logger.warn(
        { status: response.status, error },
        'Shield encryption session request failed'
      );
      return NextResponse.json(
        { message: 'Failed to create encryption session' },
        { status: response.status }
      );
    }

    const data = await response.json();
    return NextResponse.json({ session: data.session_id });
  } catch (err) {
    logger.error({ err }, 'Encryption session error');
    return handleApiError(err);
  }
}

