+  };
+  shield: {
+    url: string;
+    publishableKey?: string;
+    secretKey?: string;
+    encryptionShare?: string;
+  };
+}
+
+const requiredEnvByFeature: Record<ServerEnvFeature, string[]> = {
+  database: ['DATABASE_URL'],
+  auth: ['APP_JWT_SECRET'],
+  openfort: ['OPENFORT_SECRET_KEY'],
+  captcha: ['RECAPTCHA_SECRET_KEY'],
+  email: [
+    'SMTP_HOST',
